#include <cstdio>

struct Report {
    Report()              { std::puts("constructed"); }
    Report(const Report&) { std::puts("copied"); }
    Report(Report&&)      { std::puts("moved"); }
    ~Report()             { std::puts("destroyed"); }
};

Report make() {
    return Report{};      // prvalue: C++17 guarantees NO copy, NO move
}

int main() {
    Report r = make();
    std::puts("done");
}

